import [printf] from "std/c.bpl";

struct Counter {
    value: int,

    # Method: 'this' is a pointer to the Counter instance
    frame increment(this: *Counter) {
        this.value = this.value + 1;
    }

    frame decrement(this: *Counter) {
        this.value = this.value - 1;
    }

    frame add(this: *Counter, amount: int) {
        this.value = this.value + amount;
    }

    frame print(this: *Counter) {
        printf("Counter value: %d\n", this.value);
    }
}

frame main() ret int {
    local counter: Counter = Counter { value: 0 };

    counter.print();       # Counter value: 0

    counter.increment();
    counter.increment();
    counter.print();       # Counter value: 2

    counter.add(10);
    counter.print();       # Counter value: 12

    counter.decrement();
    counter.print();       # Counter value: 11

    return 0;
}

import [printf] from "std/c.bpl";

struct Rectangle {
    width: int,
    height: int,

    # Method that returns a value
    frame area(this: *Rectangle) ret int {
        return this.width * this.height;
    }

    frame perimeter(this: *Rectangle) ret int {
        return 2 * (this.width + this.height);
    }

    # Method that returns bool
    frame isSquare(this: *Rectangle) ret bool {
        return this.width == this.height;
    }

    # Method comparing with another rectangle
    frame equals(this: *Rectangle, other: *Rectangle) ret bool {
        return this.width == other.width && this.height == other.height;
    }
}

frame main() ret int {
    local rect1: Rectangle = Rectangle { width: 10, height: 5 };
    local rect2: Rectangle = Rectangle { width: 5, height: 5 };

    printf("Rectangle 1: %d x %d\n", rect1.width, rect1.height);
    printf("  Area: %d\n", rect1.area());
    printf("  Perimeter: %d\n", rect1.perimeter());
    printf("  Is square: %d\n", rect1.isSquare());

    printf("\nRectangle 2: %d x %d\n", rect2.width, rect2.height);
    printf("  Area: %d\n", rect2.area());
    printf("  Is square: %d\n", rect2.isSquare());

    printf("\nAre they equal? %d\n", rect1.equals(&rect2));

    return 0;
}

import [printf] from "std/c.bpl";

struct Math {
    # Static method: no 'this' parameter
    # Called on the type, not an instance
    frame abs(value: int) ret int {
        if (value < 0) {
            return -value;
        }
        return value;
    }

    frame max(a: int, b: int) ret int {
        if (a > b) {
            return a;
        }
        return b;
    }

    frame min(a: int, b: int) ret int {
        if (a < b) {
            return a;
        }
        return b;
    }

    frame clamp(value: int, minVal: int, maxVal: int) ret int {
        if (value < minVal) {
            return minVal;
        }
        if (value > maxVal) {
            return maxVal;
        }
        return value;
    }
}

frame main() ret int {
    # Static methods are called on the type name
    printf("abs(-5): %d\n", Math.abs(-5));
    printf("abs(5): %d\n", Math.abs(5));

    printf("\nmax(10, 20): %d\n", Math.max(10, 20));
    printf("min(10, 20): %d\n", Math.min(10, 20));

    printf("\nclamp(50, 0, 100): %d\n", Math.clamp(50, 0, 100));
    printf("clamp(-10, 0, 100): %d\n", Math.clamp(-10, 0, 100));
    printf("clamp(150, 0, 100): %d\n", Math.clamp(150, 0, 100));

    return 0;
}

