struct Point {
    x: int,
    y: int,

    frame setX(this: *Point, x: int) ret *Point {
        this.x = x;
        return this;
    }

    frame setY(this: *Point, y: int) ret *Point {
        this.y = y;
        return this;
    }

    frame move(this: *Point, dx: int, dy: int) ret *Point {
        this.x = this.x + dx;
        this.y = this.y + dy;
        return this;
    }

    frame print(this: *Point) {
        printf("Point(%d, %d)\n", this.x, this.y);
    }
}

frame main() ret int {
    # Method chaining with Point
    local p: Point = Point { x: 0, y: 0 };

    # Chain multiple method calls
    p.setX(5).setY(10).print();

    p.move(3, 2).move(1, 1).print();

    return 0;
}

