struct Color {
    r: int,
    g: int,
    b: int,

    # Factory methods - create instances with specific values
    frame red() ret Color {
        return Color { r: 255, g: 0, b: 0 };
    }

    frame green() ret Color {
        return Color { r: 0, g: 255, b: 0 };
    }

    frame blue() ret Color {
        return Color { r: 0, g: 0, b: 255 };
    }

    frame white() ret Color {
        return Color { r: 255, g: 255, b: 255 };
    }

    frame black() ret Color {
        return Color { r: 0, g: 0, b: 0 };
    }

    frame rgb(r: int, g: int, b: int) ret Color {
        return Color { r: r, g: g, b: b };
    }

    # Instance method
    frame print(this: *Color) {
        printf("RGB(%d, %d, %d)\n", this.r, this.g, this.b);
    }
}

frame main() ret int {
    # Use factory methods to create colors
    local myRed: Color = Color.red();
    local myGreen: Color = Color.green();
    local custom: Color = Color.rgb(128, 64, 255);

    printf("Red: ");
    myRed.print();

    printf("Green: ");
    myGreen.print();

    printf("Custom: ");
    custom.print();

    return 0;
}

