import [printf] from "std/c.bpl";

struct BankAccount {
    balance: int,
    accountNumber: string,

    frame deposit(this: *BankAccount, amount: int) {
        this.balance = this.balance + amount;
        printf("Deposited %d. New balance: %d\n", amount, this.balance);
    }

    frame withdraw(this: *BankAccount, amount: int) ret bool {
        if (amount > this.balance) {
            printf("Insufficient funds! Balance: %d\n", this.balance);
            return false;
        }
        this.balance = this.balance - amount;
        printf("Withdrew %d. New balance: %d\n", amount, this.balance);
        return true;
    }

    frame getBalance(this: *BankAccount) ret int {
        return this.balance;
    }
}

frame main() ret int {
    local account: BankAccount = BankAccount {
        balance: 100,
        accountNumber: "12345"
    };

    printf("Account %s\n\n", account.accountNumber);

    account.deposit(50);
    account.withdraw(30);
    account.withdraw(200);  # Should fail

    printf("\nFinal balance: %d\n", account.getBalance());

    return 0;
}
